// Exercise the actual Web entry point and its GET JSON error contract in fresh PHP processes.
function routeProbe(array $query):array{global $root;$file=$root.'/route-probe.php';$bootstrap=var_export(BASE_PATH.'/app/bootstrap.php',true);$qs=var_export(http_build_query($query),true);file_put_contents($file,'<?php require '.$bootstrap.'; $_SERVER["REQUEST_METHOD"]="GET";$_SERVER["QUERY_STRING"]='.$qs.';parse_str($_SERVER["QUERY_STRING"],$_GET);register_shutdown_function(function(){fwrite(STDERR,"probe-status:".(http_response_code()?:200));});Namira\\Web::run();');$process=proc_open([PHP_BINARY,$file],[1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Cannot start route probe');$output=stream_get_contents($pipes[1]);$errors=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);if($exit!==0)throw new RuntimeException('Route probe failed: '.$errors);preg_match('/probe-status:(\d+)/',$errors,$status);return ['status'=>(int)($status[1]??0),'data'=>json_decode($output,true,128,JSON_THROW_ON_ERROR)];}
